import axios from 'axios';

const API_URL = 'https://localhost:7285/api'; // Backend API URL'si

// Axios instance oluşturma
const axiosInstance = axios.create({
    baseURL: API_URL,
    headers: {
        'Content-Type': 'application/json'
    },
    timeout: 10000
});

// Axios interceptor
axiosInstance.interceptors.response.use(
    response => response.data,
    error => {
        console.error('API Hatası:', {
            message: error.message,
            status: error.response?.status,
            data: error.response?.data
        });

        if (error.code === 'ECONNABORTED') {
            return Promise.reject({ 
                success: false, 
                message: 'İstek zaman aşımına uğradı. Lütfen tekrar deneyin.' 
            });
        }

        if (!error.response) {
            return Promise.reject({ 
                success: false, 
                message: 'Sunucuya bağlanılamıyor. Lütfen internet bağlantınızı kontrol edin.' 
            });
        }

        return Promise.reject(error.response.data || { 
            success: false, 
            message: 'Bir hata oluştu' 
        });
    }
);

// Store1 Servisleri
export const getStore1AllStocks = async () => {
    try {
        const response = await axiosInstance.get('/Store1/StockGetAll');
        if (response && response.success) {
            return {
                success: response.success,
                message: response.message,
                store1Stocks: response.store1Stocks || []
            };
        } else {
            throw new Error(response?.message || 'Stok verileri alınamadı');
        }
    } catch (error) {
        console.error('Store1 - Stok verileri alınırken hata:', error);
        throw error;
    }
};

export const getStore1CategoryStocks = async () => {
    try {
        return await axiosInstance.get('/Store1/CategoryStock');
    } catch (error) {
        console.error('Store1 - Kategori stok verileri alınırken hata:', error);
